-- v5 satış ödeme kırılımı ve ek ürün/hizmet kalemleri.
-- Mevcut verileri silmez; birden fazla kez çalıştırılabilir.
-- Uygulamadan önce veritabanı yedeği alın.

BEGIN;

ALTER TABLE IF EXISTS "Sales"
    ADD COLUMN IF NOT EXISTS "CashAmount" numeric(18,2) NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS "CardAmount" numeric(18,2) NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS "CardInstallments" integer NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS "ExtrasTotal" numeric(18,2) NOT NULL DEFAULT 0;

CREATE TABLE IF NOT EXISTS "SaleExtras" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "TenantId" integer NOT NULL,
    "SaleId" integer NOT NULL,
    "Kind" text NOT NULL DEFAULT 'Product',
    "Description" text NOT NULL,
    "Quantity" integer NOT NULL DEFAULT 1,
    "UnitPrice" numeric(18,2) NOT NULL DEFAULT 0,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS "IX_SaleExtras_TenantId_SaleId" ON "SaleExtras" ("TenantId", "SaleId");

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_SaleExtras_Tenant_Sale') THEN
        ALTER TABLE "SaleExtras"
            ADD CONSTRAINT "FK_SaleExtras_Tenant_Sale"
            FOREIGN KEY ("TenantId", "SaleId") REFERENCES "Sales" ("TenantId", "Id") ON DELETE CASCADE;
    END IF;
END $$;

-- Eski kayıtlarda tek tutarlı ödeme vardı; ödeme yöntemine göre nakit/kart alanlarına taşınır.
UPDATE "Sales"
SET "CashAmount" = "PaidAmount"
WHERE "CashAmount" = 0 AND "CardAmount" = 0 AND "PaidAmount" > 0
  AND "PaymentMethod" IN ('Cash', 'Credit');

UPDATE "Sales"
SET "CardAmount" = "PaidAmount"
WHERE "CashAmount" = 0 AND "CardAmount" = 0 AND "PaidAmount" > 0
  AND "PaymentMethod" IN ('Card', 'Bank');

-- Migration postgres gibi farklı bir kullanıcıyla çalıştırıldıysa yeni tablo
-- uygulamanın kullanıcısına ait olmalıdır; aksi halde API 42501 alır.
DO $$
DECLARE owner_name text;
BEGIN
    SELECT tableowner INTO owner_name
    FROM pg_tables
    WHERE schemaname = current_schema() AND tablename = 'Sales';
    IF owner_name IS NOT NULL AND owner_name <> current_user THEN
        EXECUTE format('ALTER TABLE "SaleExtras" OWNER TO %I', owner_name);
        EXECUTE format('ALTER SEQUENCE "SaleExtras_Id_seq" OWNER TO %I', owner_name);
    END IF;
END $$;

COMMIT;
